  {
    "id": "fetchPageviews1",
    "type": "core.action.http.v2",
    "typeVersion": "2.3",
    "display": {
      "label": "Fetch Pageviews"
    },
    "inputs": {
      "branches": [],
      "timeout": "PT15M",
      "retryCount": 0,
      "errorHandlingEnabled": true
    }
  },
  {
    "id": "filterHighViews",
    "type": "core.action.transform.filter",
    "typeVersion": "1.1",
    "display": { "label": "Filter views > 500" },
    "inputs": {
      "collection": "$vars.fetchPageviews1.output.body.items",
      "operations": [
        {
          "id": "op1",
          "type": "filter",
          "config": {
            "operation": "and",
            "filters": [
              { "id": "f1", "field": "views", "condition": "greater_than", "value": 500 }
            ]
          }
        }
      ]
    },
    "outputs": {
      "output": {
        "type": "array",
        "description": "The transformed data result",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "sumViews",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": { "label": "Sum views" },
    "inputs": {
      "script": "var items = $vars.filterHighViews.output; var total = 0; for (var i = 0; i < items.length; i++) { total += items[i].views; } return { total: total };"
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "endSuccess",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "Done" },
    "inputs": {},
    "outputs": {
      "result": {
        "source": "=js:String($vars.sumViews.output.total)"
      }
    }
  },
  {
    "id": "endError",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "Article not found" },
    "inputs": {},
    "outputs": {
      "result": {
        "source": "=js:'Article not found'"
      }
    }
  }
],

